additionalExercises.referenceSolution:
#include <stdio.h>
#include <string.h>

typedef struct {
    char name[21];
    long long qty;
} Item;

Item *find_item(Item *items, int n, const char *name) {
    for (Item *p = items; p != items + n; p++) {
        if (strcmp(p->name, name) == 0) {
            return p;
        }
    }
    return NULL;
}

int main(void) {
    Item items[100];
    int n = 0;
    char cmd[6];
    char name[21];
    long long qty;
    while (scanf("%5s %20s", cmd, name) == 2) {
        Item *p = find_item(items, n, name);
        if (strcmp(cmd, "add") == 0) {
            scanf("%lld", &qty);
            if (p == NULL) {
                p = &items[n++];
                strcpy(p->name, name);
                p->qty = 0;
            }
            p->qty += qty;
        } else if (strcmp(cmd, "take") == 0) {
            scanf("%lld", &qty);
            if (p == NULL || p->qty < qty) {
                printf("ERROR\n");
            } else {
                p->qty -= qty;
                printf("OK\n");
            }
        } else {
            printf("%lld\n", p == NULL ? 0 : p->qty);
        }
    }
    for (int i = 0; i < n - 1; i++) {
        int best = i;
        for (int j = i + 1; j < n; j++) {
            if (strcmp(items[j].name, items[best].name) < 0) {
                best = j;
            }
        }
        Item tmp = items[i];
        items[i] = items[best];
        items[best] = tmp;
    }
    printf("---\n");
    for (int i = 0; i < n; i++) {
        if (items[i].qty > 0) {
            printf("%s %lld\n", items[i].name, items[i].qty);
        }
    }
    return 0;
}

