#include <stdio.h>

typedef enum { END, START } Kind;

typedef struct {
    int minute;
    Kind kind;
} Event;

int goes_before(const Event *a, const Event *b) {
    if (a->minute != b->minute) {
        return a->minute < b->minute;
    }
    return a->kind < b->kind;
}

int main(void) {
    Event events[1000];
    int n;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        int h1, m1, h2, m2;
        scanf("%d:%d %d:%d", &h1, &m1, &h2, &m2);
        events[2 * i] = (Event){h1 * 60 + m1, START};
        events[2 * i + 1] = (Event){h2 * 60 + m2, END};
    }
    int total = 2 * n;
    for (int i = 0; i < total - 1; i++) {
        int best = i;
        for (int j = i + 1; j < total; j++) {
            if (goes_before(&events[j], &events[best])) {
                best = j;
            }
        }
        Event tmp = events[i];
        events[i] = events[best];
        events[best] = tmp;
    }
    int current = 0, rooms = 0;
    for (const Event *e = events; e != events + total; e++) {
        if (e->kind == START) {
            current++;
            if (current > rooms) {
                rooms = current;
            }
        } else {
            current--;
        }
    }
    printf("%d\n", rooms);
    return 0;
}

