additionalExercises.referenceSolution:
#include <stdio.h>
#include <string.h>

#define MAX_DIGITS 260

typedef struct {
    int digits[MAX_DIGITS];
    int len;
} BigNum;

BigNum parse(const char *s) {
    BigNum x = {{0}, 0};
    int n = (int)strlen(s);
    for (int i = 0; i < n; i++) {
        x.digits[i] = s[n - 1 - i] - '0';
    }
    x.len = n;
    return x;
}

void add_to(BigNum *acc, const BigNum *x) {
    int len = acc->len > x->len ? acc->len : x->len;
    int carry = 0;
    for (int i = 0; i < len; i++) {
        int sum = acc->digits[i] + x->digits[i] + carry;
        acc->digits[i] = sum % 10;
        carry = sum / 10;
    }
    if (carry > 0) {
        acc->digits[len] = carry;
        len++;
    }
    acc->len = len;
}

void print_big(const BigNum *x) {
    for (int i = x->len - 1; i >= 0; i--) {
        printf("%d", x->digits[i]);
    }
    printf("\n");
}

int main(void) {
    int n;
    scanf("%d", &n);
    BigNum total = parse("0");
    char s[201];
    for (int i = 0; i < n; i++) {
        scanf("%200s", s);
        BigNum x = parse(s);
        add_to(&total, &x);
    }
    print_big(&total);
    return 0;
}

